// These checks generate a server without authored tools. Applications implement
// the generated protocol methods while transport, discovery and authorization
// remain generated by the same MCP plugin used for static tools.
package codegen

import (
	"testing"

	"github.com/stretchr/testify/assert"
	mcpexpr "goa.design/goa-ai/expr/mcp"
	"goa.design/goa/v3/expr"
)

func TestMCPDynamicToolMethods(t *testing.T) {
	for _, dynamic := range []bool{false, true} {
		name := "disabled"
		if dynamic {
			name = "enabled"
		}
		t.Run(name, func(t *testing.T) {
			builder := newMCPExprBuilder(&expr.ServiceExpr{Name: "catalog"}, &mcpexpr.MCPExpr{DynamicTools: dynamic})
			service := builder.BuildServiceExpr()
			assert.Equal(t, dynamic, service.Method("tools/list") != nil)
			assert.Equal(t, dynamic, service.Method("tools/call") != nil)
		})
	}
}

func TestMCPDynamicToolsGeneratedTransport(t *testing.T) {
	runMCPPeer(t, "dynamic-tools.local", dynamicToolsDesign, dynamicToolsRuntime)
}

func TestMCPDynamicToolsGeneratedExample(t *testing.T) {
	runMCPServerConstructorExample(t, dynamicToolsDesign, "")
}

const dynamicToolsDesign = `package design
import (
 . "goa.design/goa-ai/dsl"
 . "goa.design/goa/v3/dsl"
)
var _=API("dynamic_tools",func(){Description("Serve tools selected at runtime")})
var access=JWTSecurity("access",func(){Scope("tools:use","List and invoke permitted tools")})
var _=Service("catalog",func(){
 MCP("catalog","1",func(){DynamicTools();Security(access,func(){Scope("tools:use")})})
 JSONRPC(func(){POST("/mcp")})
})
`

const dynamicToolsRuntime = `package dynamictools
import (
 "context"
 "crypto/ed25519"
 "crypto/rand"
 "encoding/json"
 "fmt"
 "net/http"
 "net/http/httptest"
 "net/url"
 "strings"
 "sync/atomic"
 "testing"
 "time"

 "github.com/go-jose/go-jose/v4"
 "github.com/go-jose/go-jose/v4/jwt"
 "github.com/stretchr/testify/assert"
 "github.com/stretchr/testify/require"
 genmcp "dynamic-tools.local/gen/mcp_catalog"
 genclient "dynamic-tools.local/gen/jsonrpc/mcp_catalog/client"
 genserver "dynamic-tools.local/gen/jsonrpc/mcp_catalog/server"
 mcpruntime "goa.design/goa-ai/runtime/mcp"
 goahttp "goa.design/goa/v3/http"
 goa "goa.design/goa/v3/pkg"
)

type service struct {
 *genmcp.MCPAdapter
 calls atomic.Int32
 scalar atomic.Bool
 name atomic.Value
}
var _ genmcp.Service=(*service)(nil)

func(s *service)ToolsList(ctx context.Context,p *genmcp.ToolsListPayload)(*genmcp.ToolsListResult,error){
 if _,ok:=mcpruntime.ResourcePrincipalFromContext(ctx);!ok{return nil,fmt.Errorf("verified principal missing")}
 if p.Cursor!=nil{return nil,goa.PermanentError("invalid_params","unknown cursor")}
 outputSchema:=json.RawMessage("{\"type\":\"object\"}")
 if s.scalar.Load(){outputSchema=json.RawMessage("{\"type\":\"number\"}")}
 return &genmcp.ToolsListResult{ResultType:"complete",TTLMs:0,CacheScope:"private",Tools:[]*genmcp.ToolInfo{
  {Name:s.name.Load().(string),InputSchema:json.RawMessage("{\"type\":\"object\"}"),OutputSchema:outputSchema},
 }},nil
}
func(s *service)ToolsCall(ctx context.Context,p *genmcp.ToolsCallPayload)(*genmcp.ToolsCallResult,error){
 if _,ok:=mcpruntime.ResourcePrincipalFromContext(ctx);!ok{return nil,fmt.Errorf("verified principal missing")}
 if p.Name!=s.name.Load().(string){return nil,goa.PermanentError("invalid_params","unknown tool")}
 s.calls.Add(1)
 text:="runtime result"
 structured:=json.RawMessage("{\"value\":42}")
 if s.scalar.Load(){structured=json.RawMessage("42")}
 return &genmcp.ToolsCallResult{Outcome:genmcp.NewToolsCallOutcomeComplete(&genmcp.ToolsCallCompleteResult{
  Content:[]*genmcp.ContentItem{{Type:"text",Text:&text}},StructuredContent:structured,
 })},nil
}

type authenticatedDoer struct {client *http.Client;token string}
func(d authenticatedDoer)Do(r *http.Request)(*http.Response,error){
 r.Header.Set("Authorization","Bearer "+d.token)
 return d.client.Do(r)
}

func TestDynamicTools(t *testing.T){
 mux:=goahttp.NewMuxer()
 peer:=httptest.NewTLSServer(mux);defer peer.Close()
 public,private,err:=ed25519.GenerateKey(rand.Reader);require.NoError(t,err)
 signer,err:=jose.NewSigner(jose.SigningKey{Algorithm:jose.EdDSA,Key:private},(&jose.SignerOptions{}).WithType("at+jwt"));require.NoError(t,err)
 token,err:=jwt.Signed(signer).Claims(jwt.Claims{Issuer:peer.URL,Subject:"reader",Audience:jwt.Audience{peer.URL+"/mcp"},Expiry:jwt.NewNumericDate(time.Now().Add(time.Hour)),IssuedAt:jwt.NewNumericDate(time.Now()),ID:"test"}).Claims(map[string]any{"client_id":"client","scope":"tools:use"}).Serialize();require.NoError(t,err)
 owner,err:=mcpruntime.NewJWTResourceServer(mcpruntime.JWTResource{Issuer:peer.URL,Resource:peer.URL+"/mcp",Keys:jose.JSONWebKeySet{Keys:[]jose.JSONWebKey{{Key:public}}},Algorithms:[]jose.SignatureAlgorithm{jose.EdDSA}});require.NoError(t,err)
 s:=&service{MCPAdapter:genmcp.NewMCPAdapter(nil,nil)};s.name.Store("first")
 server:=genserver.New(genmcp.NewEndpoints(s),mux,goahttp.RequestDecoder,goahttp.ResponseEncoder,nil,owner)
 server.Mount(mux)
 location,err:=url.Parse(peer.URL);require.NoError(t,err)
 client:=genclient.NewClient(location.Scheme,location.Host,authenticatedDoer{peer.Client(),token},goahttp.RequestEncoder,goahttp.ResponseDecoder,false)
 discovered,err:=client.ServerDiscover()(t.Context(),&genmcp.DiscoverPayload{});require.NoError(t,err)
 assert.NotNil(t,discovered.(*genmcp.DiscoverResult).Capabilities.Tools)
 caller,err:=genclient.NewCaller(client,mcpruntime.ClientInfo{Name:"test",Version:"1"},mcpruntime.InputSupport{},mcpruntime.HTTPRetryPolicy{});require.NoError(t,err)
 for _,name:=range []string{"first","second"}{
  s.name.Store(name)
  listed,err:=client.ToolsList()(t.Context(),&genmcp.ToolsListPayload{});require.NoError(t,err)
  require.Len(t,listed.(*genmcp.ToolsListResult).Tools,1)
  assert.Equal(t,name,listed.(*genmcp.ToolsListResult).Tools[0].Name)
  result,err:=caller.CallTool(t.Context(),mcpruntime.CallRequest{Tool:name,Payload:json.RawMessage("{}")});require.NoError(t,err)
  assert.JSONEq(t,"{\"value\":42}",string(result.StructuredContent))
 }
 _,err=caller.CallTool(t.Context(),mcpruntime.CallRequest{Tool:"first",Payload:json.RawMessage("{}")});require.Error(t,err)
 assert.EqualValues(t,2,s.calls.Load())
 // A modern client receives a scalar exactly as returned by the implementation.
 s.scalar.Store(true)
 listed,err:=client.ToolsList()(t.Context(),&genmcp.ToolsListPayload{});require.NoError(t,err)
 assert.JSONEq(t,"{\"type\":\"number\"}",string(listed.(*genmcp.ToolsListResult).Tools[0].OutputSchema))
 scalar,err:=caller.CallTool(t.Context(),mcpruntime.CallRequest{Tool:"second",Payload:json.RawMessage("{}")});require.NoError(t,err)
 assert.Equal(t,"42",string(scalar.StructuredContent))
 s.scalar.Store(false)
 for _,version:=range []string{mcpruntime.ProtocolVersion,mcpruntime.LegacyProtocolVersion}{
  for _,method:=range []string{"tools/list","tools/call"}{
   params:="{}"
   if method=="tools/call"{params="{\"name\":\"second\",\"arguments\":{}}"}
   if version==mcpruntime.ProtocolVersion{
    params=strings.TrimSuffix(params,"}")
    if len(params)>1{params+=","}
    params+=fmt.Sprintf("\"_meta\":{\"io.modelcontextprotocol/protocolVersion\":%q,\"io.modelcontextprotocol/clientCapabilities\":{}}}",version)
   }
   for _,credential:=range []string{"","invalid",token}{
    body:=fmt.Sprintf("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":%q,\"params\":%s}",method,params)
    request:=httptest.NewRequest(http.MethodPost,peer.URL+"/mcp",strings.NewReader(body))
    request.Header.Set("Content-Type","application/json");request.Header.Set("Accept","application/json, text/event-stream")
    request.Header.Set("MCP-Protocol-Version",version);request.Header.Set("Mcp-Method",method)
    if method=="tools/call"{request.Header.Set("Mcp-Name","second")}
    if credential!=""{request.Header.Set("Authorization","Bearer "+credential)}
    before:=s.calls.Load()
    response:=httptest.NewRecorder();server.ServeHTTP(response,request)
    if credential!=token{assert.Equal(t,http.StatusUnauthorized,response.Code,response.Body.String());assert.Equal(t,before,s.calls.Load());continue}
    require.Equal(t,http.StatusOK,response.Code,response.Body.String())
    assert.NotContains(t,response.Body.String(),"\"error\"")
    assert.Contains(t,response.Body.String(),map[string]string{"tools/list":"inputSchema","tools/call":"structuredContent"}[method])
    if version==mcpruntime.LegacyProtocolVersion{assert.NotContains(t,response.Body.String(),"\"outcome\"");assert.NotContains(t,response.Body.String(),"\"resultType\"")}
   }
  }
 }
}

func TestDynamicContentValidation(t *testing.T){
 peer:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  w.Header().Set("Content-Type","application/json")
  var request struct{ID json.RawMessage}
  if err:=json.NewDecoder(r.Body).Decode(&request);err!=nil{t.Error(err);return}
  // The transport must reject a selected image without its required data.
  _,err:=w.Write([]byte("{\"jsonrpc\":\"2.0\",\"id\":"+string(request.ID)+",\"result\":{\"resultType\":\"complete\",\"content\":[{\"type\":\"image\",\"mimeType\":\"image/png\"}]}}"))
  if err!=nil{t.Error(err)}
 }));defer peer.Close()
 location,err:=url.Parse(peer.URL);require.NoError(t,err)
 client:=genclient.NewClient(location.Scheme,location.Host,peer.Client(),goahttp.RequestEncoder,goahttp.ResponseDecoder,false)
 _,err=client.ToolsCall()(t.Context(),&genmcp.ToolsCallPayload{Name:"runtime",Arguments:json.RawMessage("{}")})
 require.Error(t,err)
 assert.Contains(t,err.Error(),"data")
}
`
